<?php
// SC\Passkey with WebAuthn Level 3's own test vectors (generated from the W3C specification's
// source; RP ID example.org, origin https://example.org): registration and then authentication of
// ES256, RS256 and Ed25519 credentials, what's refused with its reason, the options, and mistakes.
require __DIR__ . '/check.inc';

function url(string $hex): string {
    return rtrim(strtr(base64_encode(hex2bin($hex)), '+/', '-_'), '=');
}
function registration(array $v): string {
    $id = url($v['credential_id']);
    return json_encode(['id' => $id, 'rawId' => $id, 'type' => 'public-key', 'clientExtensionResults' => new stdClass(),
        'response' => ['clientDataJSON' => url($v['reg_client']), 'attestationObject' => url($v['attestation'])]]);
}
function authentication(array $v, string $signatureHex): string {
    $id = url($v['credential_id']);
    return json_encode(['id' => $id, 'rawId' => $id, 'type' => 'public-key', 'clientExtensionResults' => new stdClass(),
        'response' => ['clientDataJSON' => url($v['auth_client']), 'authenticatorData' => url($v['auth_data']), 'signature' => url($signatureHex)]]);
}
function reason(callable $call): string {
    try {
        $call();
    } catch (SC\PasskeyException $e) {
        return $e->getReason();
    }
    return '';
}

