$pk = new SC\Passkey('example.org', 'Example', ['https://example.org']);

foreach (['none-es256' => -7, 'packed-rs256' => -257, 'packed-eddsa' => -8] as $name => $alg) {
    $v = $vectors[$name];
    $made = $pk->verifyRegistration(registration($v), url($v['reg_challenge']));
    check($made['id'] === url($v['credential_id']), "$name: the credential id");
    check($made['algorithm'] === $alg, "$name: the algorithm");
    check(is_string($made['publicKey']) && $made['publicKey'] !== '', "$name: a public key");
    check(preg_match('/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/', $made['aaguid']) === 1, "$name: the AAGUID as a UUID");
    check(is_bool($made['backedUp']) && is_bool($made['userVerified']), "$name: flags as booleans");
    check(SC\Passkey::credentialId(registration($v)) === $made['id'], "$name: credentialId()");
    $used = $pk->verifyAuthentication(authentication($v, $v['signature']), url($v['auth_challenge']), $made['publicKey'], $made['signCount']);
    check($used['id'] === $made['id'], "$name: signed in");
    check(array_key_exists('userHandle', $used) && is_int($used['signCount']), "$name: the assertion's fields");
    $changed = $v['signature'];
    $changed[20] = $changed[20] === '0' ? '1' : '0';
    check(reason(fn() => $pk->verifyAuthentication(authentication($v, $changed), url($v['auth_challenge']), $made['publicKey'], $made['signCount'])) === 'signature',
        "$name: a changed signature is refused");
    check(reason(fn() => $pk->verifyAuthentication(authentication($v, $v['signature']), url($v['reg_challenge']), $made['publicKey'], $made['signCount'])) === 'challenge',
        "$name: another challenge is refused");
}

$v = $vectors['none-es256-crossOrigin'];
check(reason(fn() => $pk->verifyRegistration(registration($v), url($v['reg_challenge']))) === 'cross_origin', 'a cross-origin frame is refused');
$v = $vectors['packed-es384'];
check(reason(fn() => $pk->verifyRegistration(registration($v), url($v['reg_challenge']))) === 'algorithm', 'ES384 is refused');
$other = new SC\Passkey('example.org', 'Example', ['https://*.example.org']);
$v = $vectors['none-es256'];
check(reason(fn() => $other->verifyRegistration(registration($v), url($v['reg_challenge']))) === 'origin', 'the bare domain isn\'t under its wildcard');
check(reason(fn() => $pk->verifyRegistration('not json', url($v['reg_challenge']))) === 'format', 'not JSON');
try {
    $pk->verifyRegistration('{}', url($v['reg_challenge']));
} catch (SC\PasskeyException $e) {
    check($e instanceof SC\Exception, 'SC\PasskeyException is an SC\Exception');
    check($e->getMessage() !== '', 'with a message');
}

// Options, ready for json_encode() and sc-passkey.js.
$options = $pk->registrationOptions('user-7', 'roelof', 'Roelof', ['AAAA', ['id' => 'AQID', 'transports' => ['usb']]]);
check($options['rp'] === ['id' => 'example.org', 'name' => 'Example'], 'rp');
check($options['user']['id'] === 'dXNlci03' && $options['user']['displayName'] === 'Roelof', 'user');
check(strlen($options['challenge']) === 43, 'a 32-byte challenge');
check(array_column($options['pubKeyCredParams'], 'alg') === [-7, -8, -257], 'ES256, EdDSA, RS256');
check($options['excludeCredentials'][1] === ['type' => 'public-key', 'id' => 'AQID', 'transports' => ['usb']], 'exclude with transports');
check($options['attestation'] === 'none' && $options['authenticatorSelection']['userVerification'] === 'preferred', 'none, preferred');
check($options['timeout'] === 300000, 'five minutes');
$asked = $pk->authenticationOptions(['AAAA'], 60000, 'required');
check($asked['rpId'] === 'example.org' && $asked['allowCredentials'][0]['id'] === 'AAAA', 'authentication options');
check($asked['timeout'] === 60000 && $asked['userVerification'] === 'required', 'its timeout and user verification');
check(json_decode(json_encode($asked), true) === $asked, 'json_encode() round trip');

// Mistakes are SC\Exception, not a reason.
check(throws(fn() => new SC\Passkey('example.org', 'x', ['http://example.org'])), 'an http origin');
check(throws(fn() => new SC\Passkey('example.org', 'x', ['https://*.example.com'])), 'a wildcard elsewhere');
check(throws(fn() => $pk->registrationOptions('', 'roelof')), 'an empty user id');
check(throws(fn() => $pk->authenticationOptions([], 10)), 'a timeout too short');
check(throws(fn() => $pk->authenticationOptions([], 60000, 'always')), 'a user verification that isn\'t one');
check(throws(fn() => $pk->verifyRegistration(registration($v), 'not base64url!')), 'a kept challenge that isn\'t base64url');
check(!throws(fn() => reason(fn() => $pk->verifyRegistration('{}', 'AAAA')), SC\Exception::class), 'a check failing is a PasskeyException');
